fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Check if we can safely access the slice
    if start + sub.len() > main.len() {
        return false;
    }
    
    // Compare element by element
    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // If sub is empty, it's always a subarray
    if sub.is_empty() {
        return true;
    }
    
    // If sub is longer than main, it can't be a subarray
    if sub.len() > main.len() {
        return false;
    }
    
    // Check all possible starting positions
    for k in 0..=(main.len() - sub.len()) {
        if check_match_at(main, sub, k) {
            return true;
        }
    }
    
    false
}